/** Safe filename from this application's Content-Disposition header. */
export function reportFilename(disposition) {
  const match = /(?:^|;)\s*filename\s*=\s*"?([^";]+)"?/i.exec(disposition || "");
  const candidate = match?.[1]?.trim();
  // Only names generated by the server; avoid path separators or injection.
  return candidate && /^[A-Za-z0-9][A-Za-z0-9._-]*\.pdf$/i.test(candidate)
    ? candidate
    : "VISOR_OT_diagnostico.pdf";
}

/** DRF validation details can be strings or per-field arrays. */
export function reportErrorMessage(payload, status) {
  if (payload && typeof payload === "object") {
    const messages = Object.values(payload).flatMap(value =>
      typeof value === "string" ? [value] :
        Array.isArray(value) ? value.filter(item => typeof item === "string") : []
    );
    if (messages.length) return messages.join(" ");
  }
  if (status === 401) return "Tu sesión ha expirado. Vuelve a iniciar sesión.";
  if (status === 403) return "Tu usuario no tiene permiso para generar el informe.";
  if (status === 400) return "El inventario no cumple los requisitos para generar el informe.";
  return "No se pudo generar el informe (HTTP " + status + ").";
}
